package ua.empirecraft.feudal;

import java.sql.SQLException;
import java.util.*;
import static ua.empirecraft.feudal.CityMarketService.*;
import static ua.empirecraft.feudal.Database.*;
import static ua.empirecraft.feudal.Model.*;
import ua.empirecraft.feudal.FeudalService.Actor;

/** A persisted municipal mandate is the only exception to a human standing at the counter. */
public final class MarketProcurement {
    final CityMarketService m;private String replenishing="";private long lastTick;
    MarketProcurement(CityMarketService m)throws SQLException {this.m=m;
        for(String sql:List.of(
            "CREATE TABLE IF NOT EXISTS cm_procurements(id VARCHAR(36) PRIMARY KEY,market VARCHAR(36),town VARCHAR(80),spec VARCHAR(64),code VARCHAR(8),low_stock BIGINT,target_stock BIGINT,price BIGINT,daily_limit BIGINT,batch BIGINT,days INT,state VARCHAR(12),cycle BOOLEAN DEFAULT FALSE,version BIGINT DEFAULT 1,reason VARCHAR(500),author VARCHAR(36))",
            "CREATE TABLE IF NOT EXISTS cm_proc_orders(order_id VARCHAR(36) PRIMARY KEY,mandate VARCHAR(36))",
            "CREATE TABLE IF NOT EXISTS cm_proc_spend(seq BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,mandate VARCHAR(36),at_time BIGINT,amount BIGINT)"))m.db.execute(sql);
    }
    public Map<String,Object> mandate(String id)throws SQLException {var r=m.db.one("SELECT * FROM cm_procurements WHERE id=?",id);require(r!=null,"Міське доручення не знайдено.");return r;}
    static String fund(String id){return "q:"+id;}
    boolean automatic(Actor a){return a.id().equals(replenishing)&&a.id().startsWith("q:");}
    String assetOwner(String owner)throws SQLException {return owner.startsWith("q:")?"e:"+string(mandate(owner.substring(2)),"town"):"p:"+owner;}
    public String create(Actor a,String req,String market,Place p,String spec,String code,long low,long target,long price,long budget,long daily,long batch,int days){return m.once(a,req,"procurement|"+market+spec+code+low+target+price+budget+daily+batch+days,()->{
        m.manage(a,market);m.access(market,Department.GOODS,p);m.payment(market,code);m.spec(spec);String town=string(m.market(market),"town");m.s.controlTreasury(a,m.s.estate(town));
        require(low>=0&&target>low&&target<=1000000&&price>0&&budget>0&&daily>0&&daily<=CurrencyService.MAX_MONEY&&batch>0&&batch<=1000000&&Set.of(1,3,7).contains(days),"Перевірте поріг, ціль, ціну, фонд, добовий ліміт, розмір і строк заявки.");
        require(!bool(m.spec(spec),"unique_lot"),"Постійна закупівля призначена для ресурсів із дозволеного каталогу.");
        String key=id();m.db.execute("INSERT INTO cm_procurements(id,market,town,spec,code,low_stock,target_stock,price,daily_limit,batch,days,state,reason,author) VALUES(?,?,?,?,?,?,?,?,?,?,?,'RUNNING','',?)",key,market,town,spec,code,low,target,price,daily,batch,days,a.id());
        m.move("e:"+town,fund(key),code,budget);m.event(a,market,"PROCUREMENT_CREATE",key+" municipal owner="+town);return key;
    });}
    public String state(Actor a,String req,String id,String state){return m.once(a,req,"procurement-state|"+id+state,()->{
        var r=mandate(id);m.manage(a,string(r,"market"));require(!"STOPPED".equals(string(r,"state"))&&Set.of("PAUSED","RUNNING","STOPPED").contains(state),"Доручення зупинено або стан некоректний.");
        cancel(id);m.db.execute("UPDATE cm_procurements SET state=?,reason='' WHERE id=?",state,id);
        if(state.equals("STOPPED")){long free=m.s.balance(fund(id),string(r,"code"));if(free>0)m.move(fund(id),"e:"+string(r,"town"),string(r,"code"),free);}
        m.event(a,string(r,"market"),"PROCUREMENT_STATE",id+" "+state);return id;
    });}
    public String deposit(Actor a,String req,String id,Place p,long amount){return m.once(a,req,"procurement-fund|"+id+amount,()->{var r=mandate(id);m.manage(a,string(r,"market"));m.access(string(r,"market"),Department.GOODS,p);m.s.controlTreasury(a,m.s.estate(string(r,"town")));require(amount>0&&!"STOPPED".equals(string(r,"state")),"Потрібна сума й чинне доручення.");m.move("e:"+string(r,"town"),fund(id),string(r,"code"),amount);return id;});}
    public String amend(Actor a,String req,String id,Place p,long low,long target,long price,long daily,long batch){return m.once(a,req,"procurement-amend|"+id+low+target+price+daily+batch,()->{var r=mandate(id);m.manage(a,string(r,"market"));m.access(string(r,"market"),Department.GOODS,p);require(!"STOPPED".equals(string(r,"state"))&&low>=0&&target>low&&target<=1000000&&price>0&&daily>0&&daily<=CurrencyService.MAX_MONEY&&batch>0&&batch<=1000000,"Некоректні нові умови.");cancel(id);m.db.execute("UPDATE cm_procurements SET low_stock=?,target_stock=?,price=?,daily_limit=?,batch=?,version=version+1,cycle=FALSE WHERE id=?",low,target,price,daily,batch,id);return id;});}
    void cancel(String id)throws SQLException {for(var o:m.db.query("SELECT o.* FROM cm_orders o JOIN cm_proc_orders p ON p.order_id=o.id WHERE p.mandate=? AND o.state='OPEN'",id))m.cancelWork(o,"MANDATE_CHANGED");}
    void closeMarket(String market)throws SQLException {
        for(var r:m.db.query("SELECT * FROM cm_procurements WHERE market=? AND state<>'STOPPED'",market)){
            String id=string(r,"id"),code=string(r,"code");cancel(id);long free=m.s.balance(fund(id),code);
            if(free>0)m.move(fund(id),"e:"+string(r,"town"),code,free);
            m.db.execute("UPDATE cm_procurements SET state='STOPPED',reason='Ринок закрито; вільний фонд повернуто місту' WHERE id=?",id);
        }
    }
    void spent(Map<String,Object> order,long amount)throws SQLException {var relation=m.db.one("SELECT mandate FROM cm_proc_orders WHERE order_id=?",string(order,"id"));if(relation!=null)m.db.execute("INSERT INTO cm_proc_spend(mandate,at_time,amount) VALUES(?,?,?)",string(relation,"mandate"),m.s.now(),amount);}
    void reason(String id,String reason)throws SQLException {m.db.execute("UPDATE cm_procurements SET reason=? WHERE id=?",reason,id);}
    public void replenish(String id)throws SQLException {
        var r=mandate(id);if(!"RUNNING".equals(string(r,"state")))return;String market=string(r,"market"),code=string(r,"code");
        if(!m.open(market,Department.GOODS)){reason(id,"Товарний відділ або міська територія недоступні");return;}
        try{m.payment(market,code);}catch(IllegalArgumentException ex){reason(id,ex.getMessage());return;}
        String owner="e:"+string(r,"town");long stock=number(m.db.one("SELECT COALESCE(SUM(quantity),0) AS n FROM cm_assets WHERE market=? AND owner=? AND spec=?",market,owner,string(r,"spec")),"n");
        long ordered=number(m.db.one("SELECT COALESCE(SUM(o.remaining),0) AS n FROM cm_orders o JOIN cm_proc_orders p ON p.order_id=o.id WHERE p.mandate=? AND o.state='OPEN'",id),"n");
        boolean cycle=bool(r,"cycle")||stock<number(r,"low_stock");if(stock>=number(r,"target_stock"))cycle=false;m.db.execute("UPDATE cm_procurements SET cycle=? WHERE id=?",cycle,id);
        if(!cycle){reason(id,"Запас не нижчий за поріг");return;}
        long need=Math.max(0,number(r,"target_stock")-stock-ordered);if(need==0){reason(id,"Потребу вже покривають активні закупівлі");return;}
        if(number(m.db.one("SELECT COUNT(*) AS n FROM cm_assets WHERE market=? AND owner=? AND quantity>0",market,owner),"n")>=m.maxDeposits){reason(id,"Заповнено міське сховище");return;}
        long spent=number(m.db.one("SELECT COALESCE(SUM(amount),0) AS n FROM cm_proc_spend WHERE mandate=? AND at_time>?",id,m.s.now()-FeudalService.DAY),"n");
        long reserved=0;for(var o:m.db.query("SELECT o.id FROM cm_orders o JOIN cm_proc_orders p ON p.order_id=o.id WHERE p.mandate=? AND o.state='OPEN'",id))reserved=Math.addExact(reserved,m.s.balance(account(string(o,"id")),code));
        long available=Math.min(m.s.balance(fund(id),code),Math.max(0,number(r,"daily_limit")-spent-reserved));int bps=(int)number(m.tariff(market),"buyer");
        long lo=0,hi=Math.min(need,number(r,"batch"));while(lo<hi){long mid=lo+(hi-lo+1)/2;long value=multiply(mid,number(r,"price"));if(Math.addExact(value,fee(value,bps))<=available)lo=mid;else hi=mid-1;}
        if(lo==0){reason(id,"Недостатньо вільних коштів або вичерпано ковзний ліміт 24 години");return;}
        var dep=m.department(market,Department.GOODS);var p=new Place(string(m.market(market),"world"),number(dep,"cx")+.5,number(dep,"cy"),number(dep,"cz")+.5);
        replenishing=fund(id);
        try{String request=CityMarketService.id();String order=m.order(new Actor(fund(id),false),request,market,p,Department.GOODS,string(r,"spec"),"",code,"BUY",lo,number(r,"price"),(int)number(r,"days"),number(m.tariff(market),"version"),null);
            m.db.execute("MERGE INTO cm_proc_orders KEY(order_id) VALUES(?,?)",order,id);
            var completed=m.order(order);if(number(completed,"volume")>0)spent(completed,number(completed,"volume")+number(completed,"fees"));
            reason(id,"Забезпечена заявка "+order);
        }finally{replenishing="";}
    }
    void tick()throws SQLException {if(m.s.now()-lastTick<60000)return;lastTick=m.s.now();for(var r:m.db.query("SELECT id FROM cm_procurements WHERE state='RUNNING'"))replenish(string(r,"id"));}
}
